-- Every permitted order in a party must retain its bill in the scoped history.
CREATE OR REPLACE FUNCTION dg_native_bill_read(kind_value text,target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;connection jsonb;
BEGIN
 IF kind_value NOT IN('restaurant','party','bill') THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;meta:=dg_native_bill_context(kind_value,target,session_value,token_value);connection:=dg_native_bill_connection(meta->>'restaurantId',dg_native_bill_manager(meta));
 IF kind_value='restaurant' THEN RETURN connection;ELSIF kind_value='bill' THEN RETURN dg_native_bill_project(target,meta);END IF;
 RETURN jsonb_build_object('partyId',target,'bills',(SELECT coalesce(jsonb_agg(dg_native_bill_project(bill.id,meta) ORDER BY bill.created_at DESC,bill.id DESC),'[]') FROM(SELECT b.id,b.created_at FROM restaurant_bills b JOIN _dg_native_bill_origins fixed ON fixed.bill_id=b.id WHERE b.party_id=target ORDER BY b.created_at DESC,b.id DESC LIMIT 100) bill),'unbilledOrders',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',current_order.id,'number',current_order.number,'version',current_order.version,'contentVersion',current_order.content_version,'status',current_order.status,'totalMinor',coalesce((SELECT sum((line.quantity-line.cancelled_quantity)*line.unit_price_minor) FROM restaurant_order_lines line WHERE line.order_id=current_order.id),0)) ORDER BY current_order.created_at DESC,current_order.id DESC),'[]') FROM restaurant_orders current_order JOIN _dg_native_order_origins fixed ON fixed.order_id=current_order.id WHERE current_order.party_id=target AND NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id) AND EXISTS(SELECT 1 FROM restaurant_order_lines line WHERE line.order_id=current_order.id AND line.quantity>line.cancelled_quantity)),'connection',connection-ARRAY['canManage','scenario'],'automatic',meta->>'actorType'='staff' OR dg_native_order_source(meta,target),'canManage',dg_native_bill_manager(meta));
END;$dg$;

